/**
 * SRA Regulatory Boundary Guardrail
 * Enforces Legal Services Act 2007 and Section 203(3) Employment Rights Act 1996 compliance.
 * Guarantees zero unauthorized practice of law by framing all AI intelligence as an objective statutory audit.
 */

export const SRA_COMPLIANCE_DISCLAIMER = 
  'This pre-flight case audit and statutory evaluation is generated by SettlementCheck strictly for objective information and triage purposes. It does not constitute formal legal advice or create a solicitor-client relationship. Under Section 203(3) of the Employment Rights Act 1996, formal statutory advice must be delivered by your instructed independent SRA-regulated solicitor.';

const FORBIDDEN_REPLACEMENTS: Array<[RegExp, string]> = [
  [/\bwe advise you to\b/gi, 'the statutory analysis indicates you should consider'],
  [/\bour legal advice is\b/gi, 'the objective statutory evaluation shows'],
  [/\bas your solicitor\b/gi, 'for your instructed solicitor'],
  [/\bas your legal representative\b/gi, 'for your independent legal adviser'],
  [/\bI advise you to\b/gi, 'the statutory analysis suggests'],
  [/\bthis legal advice confirms\b/gi, 'this statutory audit confirms'],
  // SRA Rule 5 & Descriptive Tone Invariants
  [/\bwhat to say to your employer\b/gi, 'questions to consider with a solicitor'],
  [/\byou should ask for £?(\d[\d,]*)\b/gi, 'calculated illustrative negotiation figure of £$1'],
  [/\byou should ask for\b/gi, 'calculated illustrative negotiation range'],
  [/\byou should counter\b/gi, 'you may explore negotiating'],
  [/\bthe current offer (?:presented )?is £0\b/gi, 'no employer offer recorded'],
  [/\bdo not accept this offer\b/gi, 'this offer is below the calculated statutory baseline'],
  [/\bdo not sign this offer\b/gi, 'consider reviewing the statutory baseline before signing'],
  [/\byour employer is (?:legally )?required to pay £\d+\b/gi, 'employers customarily contribute £350 to £750 + VAT'],
  [/\bwithout prejudice proposal\b/gi, 'solicitor discussion agenda / summary of figures'],
  [/\bwithout prejudice: settlement agreement proposal\b/gi, 'solicitor discussion agenda: key figures briefing'],
  [/\byour employer cannot legally require you to waive\b/gi, 'under Section 203(3) ERA 1996, waiving employment rights requires independent legal advice'],
  // 5 Adversarial Invariants (Routledge v Grant & s.111A Scope)
  [/\byou have a (?:legal )?right to 10 days\b/gi, 'ACAS Code 4 recommends a minimum of 10 calendar days, though employers may set specific deadlines'],
  [/\byour employer cannot withdraw the offer (?:for|within) 10 days\b/gi, 'ACAS Code 4 recommends 10 calendar days, but employers can set deadlines or revoke offers prior to acceptance'],
  [/\bsection 111a protects all conversations\b/gi, 'Section 111A ERA 1996 protects pre-termination discussions strictly for standard unfair dismissal'],
  [/\bsend this (?:letter|proposal|demand) to your employer\b/gi, 'review this discussion agenda with an independent solicitor before sending'],
];

export function sanitizeAdvicePhrasing(text: string): string {
  let sanitized = text;
  for (const [regex, replacement] of FORBIDDEN_REPLACEMENTS) {
    if (regex.test(sanitized)) {
      sanitized = sanitized.replace(regex, replacement);
    }
  }
  return sanitized;
}

export function enforceSraRegulatoryBoundary(text: string): { sanitizedText: string; isModified: boolean } {
  let sanitized = sanitizeAdvicePhrasing(text);
  let isModified = sanitized !== text;

  // Ensure disclaimer presence if it's a long report
  if (!sanitized.includes('Section 203(3)') && sanitized.length > 200) {
    sanitized += `\n\n---\n**SRA Regulatory Notice**: ${SRA_COMPLIANCE_DISCLAIMER}`;
    isModified = true;
  }

  return {
    sanitizedText: sanitized,
    isModified,
  };
}

/**
 * Taxonomizes a search query or dispute context into FINANCIAL_CALCULATION vs EMOTIONAL_DISPUTE
 * so statutory guardrails enforce either financial caps (£751 / £30,000) OR Section 203 ERA 1996
 * independent solicitor rights & employer fee coverage for non-redundancy hostile exits.
 */
export function classifyStatutoryRequirementCategory(
  queryOrContext: string
): 'FINANCIAL_CALCULATION' | 'EMOTIONAL_DISPUTE' {
  const q = queryOrContext.toLowerCase();
  const emotionalDisputeTriggers = [
    'constructive dismissal',
    'discrimination',
    'bullying',
    'harassment',
    'pressured',
    'withdraw',
    'do not sign',
    "don't sign",
    'sick leave',
    'pip',
    'performance improvement',
    'protected conversation',
    'without prejudice',
    'maternity',
    'whistleblowing',
  ];

  for (const trigger of emotionalDisputeTriggers) {
    if (q.includes(trigger)) {
      return 'EMOTIONAL_DISPUTE';
    }
  }

  return 'FINANCIAL_CALCULATION';
}

/**
 * Verifies intent-calibrated statutory tokens in generated snippets
 */
export function verifyIntentCalibratedStatutoryTokens(
  text: string,
  category: 'FINANCIAL_CALCULATION' | 'EMOTIONAL_DISPUTE',
  weeklyCapGB: number = 751
): { isValid: boolean; reason?: string } {
  const lower = text.toLowerCase();

  if (category === 'EMOTIONAL_DISPUTE') {
    const hasSection203OrRights =
      lower.includes('section 203') ||
      lower.includes('era 1996') ||
      lower.includes('acas') ||
      lower.includes('equality act') ||
      lower.includes('solicitor') ||
      text.includes(`£${weeklyCapGB}`) ||
      text.includes('£30,000');

    const hasEmployerFeeGuarantee =
      lower.includes('employer') && (lower.includes('fee') || lower.includes('cost') || lower.includes('pays') || lower.includes('covers'));

    if (!hasSection203OrRights || !hasEmployerFeeGuarantee) {
      return {
        isValid: false,
        reason:
          'Emotional/dispute query copy must reference statutory protections (Section 203 ERA 1996 / ACAS / solicitor) and employer legal fee coverage.',
      };
    }
    return { isValid: true };
  }

  // Default: FINANCIAL_CALCULATION requires statutory financial caps (£751 or £30,000)
  if (!text.includes(`£${weeklyCapGB}`) && !text.includes('£30,000')) {
    return {
      isValid: false,
      reason: `Financial calculation copy missing required statutory figures (£${weeklyCapGB} or £30,000)`,
    };
  }

  return { isValid: true };
}

